    def ensure_containers_is_list(cls, v):
        """Ensure containers is a list."""
        if isinstance(v, dict):
            return [v]
        return v

    @model_validator(mode="after")
    def validate_blocking_endpoint(self):
        """Validate endpoint blocking has health_check or readinessProbe."""
        if self.blocking == "endpoint":
            has_health_check = self.health_check is not None
            has_readiness_probe = (
                self.containers
                and len(self.containers) > 0
                and self.containers[0].readinessProbe is not None
            )
            if not has_health_check and not has_readiness_probe:
                raise ValueError(
                    f"Task '{self.name}' has blocking='endpoint' but no health_check or readinessProbe"
                )
        return self


